from pathlib import Path
exec(Path('verification/state-guides/research/build-b.py').read_text(encoding='utf-8-sig').split("add('Maine'")[0])
add('New Jersey','NJ','New Jersey bookkeeping for sales evidence, employer wage reports, vendor credits and four year sales record preservation.','New Jersey payroll uses distinct withholding and wage reporting forms, while sales records need enough detail to reproduce transaction history.',[
('Sales, Exemptions And Purchase Use Tax',[1],['New Jersey sales documentation should distinguish total receipts, taxable receipts, tax due and purchases subject to use tax. Keep product descriptions, delivery evidence and exemption certificates linked to sales. Review goods and services using current classification guidance rather than relying on a broad customer or department label.','For vendor bills, preserve the invoice and destination, identify resale stock and company use separately, and send uncertain purchases to the preparer. Keep credits linked to the original bill so a later refund does not disappear into miscellaneous income or an unexplained tax adjustment.']),
('Payroll Filing And Wage Evidence',[2,3],['New Jersey employers must register for payroll tax purposes to file NJ-927, NJ-W-3 and WR-30. Those forms support different reporting functions. Preserve the submitted versions and confirmations with the wage register so a successful payment is not mistaken for completion of every wage reporting requirement.','Use employee withholding instructions and actual work location information in payroll review. Reconcile gross pay, deductions, net pay and employer contributions separately. Maintain records supporting any change affecting an employee rather than replacing the earlier form without its effective date.']),
('Income, Vendor Bills And Equipment',[],['A retailer can receive online settlements, store cash, customer deposits and owner funding through the same bank account. Preserve the source of each receipt and reconcile processing fees independently. Compare customer refunds with their original invoices and the inventory returned.','For accounts payable, match approved purchases with goods received and supplier statements. Track equipment, improvements and financing separately from merchandise and routine costs. A debt payment needs an allocation between principal and other charges supported by the loan statement. These are general accounting controls, not a promise of a tax deduction.']),
('Monthly Reports And System Changes',[],['Close bank and card reconciliations, compare supplier balances with unpaid bills and investigate old customer credits. The monthly profit and loss statement should connect to a balance sheet containing supported inventory, deposits and liabilities. Explain the effect of stock counts and damaged merchandise adjustments.','When the sales system changes, preserve item mappings, transaction exports and the date each tax setting changed. Reconcile old and new system totals across the transition. Keep payroll and sales liability schedules with the monthly package so return adjustments remain visible to the owner.']),
('Hypothetical Register Migration',[1],['Hypothetical example: a New Jersey gift shop replaces its registers and finds that the new system combines several product categories under one button. The bookkeeper exports old transaction detail, preserves the item mapping and reviews the new categories with the preparer. The scenario does not assume every item within a category shares one tax treatment.']),
('Year End And Preservation',[1],['Prepare the tax handoff with annual sales and use reconciliations, inventory support, vendor totals, payroll form confirmations, asset records and open notices. Include the register conversion explanation and any corrections posted after the annual statements were first produced.','The New Jersey sales publication requires relevant books, certificates and other tax evidence to remain available for at least four years. It also sets conditions for electronic or copied records and original destruction, so a scan alone should not be treated as blanket permission to discard everything. Confirm the record medium and retention clock before destruction; employer, federal, asset and disputed period requirements need separate schedules.'])],[('New Jersey Sales Tax Publication S&U-4','https://www.state.nj.us/treasury/taxation/pdf/pubs/sales/su4.pdf',['Sales and use record scope, four year preservation and conditional electronic record treatment.']),('New Jersey Employer Payroll Filing Options','https://www.nj.gov/treasury/taxation/businesses/payroll/payroll-filing.shtml',['Registration and separate NJ-927, NJ-W-3 and WR-30 reporting.']),('New Jersey Employer Payroll Forms','https://www.nj.gov/njbonds/treasury/taxation/prntempl.shtml',['Withholding certificates and current employer form resources.'])],['Sales publication revision is July 2022 although currently served by the agency; specific 2026 service classifications require current qualified review. No classification or rate conclusion asserted. Employer retention not generalized from sales rule.'])
add('New Mexico','NM','New Mexico bookkeeping for gross receipts, NTTC evidence, compensating tax, wage withholding and defensible electronic records.','New Mexico gross receipts tax is imposed on sellers, so the ledger needs receipt classifications and deduction evidence beyond an ordinary sales tax account.',[
('Gross Receipts And Deduction Evidence',[1,2],['New Mexico gross receipts tax is imposed on businesses and may be passed to customers; when passed on, the agency requires it to be separately stated on the invoice. Preserve the activity description and transaction location for the preparer because local location codes affect reporting.','Nontaxable Transaction Certificates relate to specific gross receipts deductions. Keep the certificate type, customer and transaction support together; the agency permits alternative evidence for many deductions but identifies exceptions. Ordinary business expenses do not automatically become gross receipts deductions. Keep net income accounting separate from the tax receipt classification.']),
('Purchase And Vendor Review',[3],['New Mexico electronic record rules require detail that supports tax computation and can be interpreted during an examination. Keep supplier identities, item descriptions, amounts, tax information and shipping facts available even where the accounting export uses product or vendor codes.','As a practical accounts payable control, flag purchases requiring compensating tax review and document the preparer decision. Separate goods acquired for resale from items used by the company, and retain the NTTC evidence actually supplied. A certificate used for one type of purchase should not silently carry over to a different activity.']),
('Wage Withholding And Workers Compensation',[4],['New Mexico requires covered employers to register and withhold state income tax, with stated exceptions requiring individual facts. Wage withholding uses a separate return from nonwage withholding. Preserve worker instructions, residence, service locations and payroll registers for review.','The agency also collects a workers compensation administration fee for covered employers and employees. Paying that fee does not provide workers compensation insurance, and unemployment reporting is through Workforce Solutions. Reconcile each liability separately rather than treating one payroll provider withdrawal as proof that every employer obligation was completed.']),
('Monthly Financial Reporting',[],['Reconcile bank accounts, customer receipts and unpaid vendor bills before presenting financial statements. Maintain a bridge from accounting income to gross receipts reported, showing deductions and adjustments with document references. A low profit month can still contain substantial gross receipts.','Review customer deposits, supplier credits, loan activity and asset purchases with the owner. Keep a separate compensating tax question list and liability schedule. Explain accounting method differences to the preparer rather than changing the reporting method solely to match a cash balance.']),
('Hypothetical Certificate Mismatch',[2],['Hypothetical example: a New Mexico design business receives a customer certificate but cannot connect its type to the service invoiced. The bookkeeper saves the contract, invoice and certificate and flags the receipt for professional deduction review. The certificate is preserved as evidence without treating its mere existence as a completed tax analysis.']),
('Year End And Retention Scope',[3,5],['Give the preparer reconciled statements, receipts by location and deduction, NTTC support, compensating tax decisions, wage reconciliations, assets and agency notices. Keep electronic code descriptions with transaction exports so the reviewer can reconstruct the reporting bridge.','NMAC 3.1.5.8 states that the Tax Administration Act sets no fixed retention time, while assessment limitations still apply. FYI-105 recommends maintaining the files for ten years because extended assessments can apply, and distinguishes the ordinary assessment period from longer cases. Treat ten years as agency advice, not an invented universal statutory minimum; federal employment, property and special industry records need their own schedules.'])],[('New Mexico Gross Receipts Overview','https://www.tax.newmexico.gov/businesses/gross-receipts-overview/',['Seller liability, separately stated passed tax, location codes and no ordinary business expense deduction.']),('New Mexico NTTC Resources','https://www.tax.newmexico.gov/businesses/non-taxable-transaction-certificates-nttc/',['Certificate types, qualifying deductions and alternative evidence limits.']),('New Mexico NMAC 3.1.5 Records','https://www.srca.nm.gov/parts/title03/03.001.0005.html',['Record sufficiency, interpretable electronic transaction detail and no fixed Tax Administration Act retention time.']),('New Mexico Withholding And Workers Compensation','https://www.tax.newmexico.gov/businesses/withholding-tax-and-workers-compensation/',['Separate wage and nonwage reporting, compensation fee distinct from insurance and separate unemployment administration.']),('New Mexico FYI-105','https://realfile.tax.newmexico.gov/FYI-105.pdf',['Compensating tax review context and ten year recommended retention distinguished from assessment periods.'])],['Specific gross receipts deductions, tribal rules, location sourcing and employee exceptions require professional review. No blanket statutory three or ten year destruction date asserted.'])
add('North Carolina','NC','North Carolina bookkeeping for contractor documents, sales and use records, employee certificates and ten year withholding preservation.','North Carolina contractor and sales files need clear activity evidence, while current employer instructions prescribe a much longer withholding retention schedule.',[
('Sales, Contractors And Transaction Evidence',[1,2],['North Carolina requires retailers, facilitators, real property contractors and consumers to keep records establishing their sales and use tax liability. Retailer records include gross income, gross sales, taxable sales, resale purchases and facilitator transaction information. Keep exemption evidence with the sale it supports.','For construction or repair work, preserve contracts, work descriptions and any applicable capital improvement documentation for professional classification. A contractor label does not settle treatment. Accounts payable should preserve purchase invoices, job use and taxes paid elsewhere so any purchase use tax decision has transaction support.']),
('Employee Certificates And Withholding',[3],['The current 2026 employer instructions require North Carolina withholding certificates such as NC-4 and identify payroll reporting duties. Keep signed employee instructions, effective dates, wage registers, amounts withheld, returns and payment confirmations. Work location and residence facts should reach payroll review before state allocations are finalized.','Reconcile periodic payments with the annual NC-3 totals and wage statements. Document corrections in both the payroll system and liability accounts. Unemployment and other employment obligations need their own account checks, and a contractor payment should not be treated as wages or exempt compensation solely from its ledger category.']),
('Vendor Files And Income Classification',[],['A renovation business can receive progress billings, customer advances and owner loans during the same week. Link each receipt to the contract or financing document and preserve changes in scope. The customer ledger should distinguish amounts billed, collected and still disputed.','For vendor bills, keep purchase approval, job delivery and payment together. Separate equipment retained by the company from materials used on a project. Track supplier credits against the original purchase and ask the preparer to resolve uncertain capitalization or tax treatment using the original documentation.']),
('Monthly Close And Tax Reconciliations',[],['Review project receipts and direct spending alongside customer aging and unpaid suppliers. Reconcile cash, cards and debt, then present a profit and loss statement and balance sheet under the agreed accounting basis. Explain unfinished work and customer advances rather than treating bank deposits as the sole revenue measure.','Maintain distinct sales tax, purchase use tax and withholding schedules. Each should connect opening liability, current activity, adjustments and payments to the filed return. Preserve the reason a transaction was reclassified so a future reviewer can reproduce the result.']),
('Hypothetical Renovation Scope Change',[1,2],['Hypothetical example: a North Carolina contractor begins with a repair order and later accepts a broader renovation contract. The bookkeeper retains both scopes, approvals, invoices and project documents and asks the preparer to evaluate the tax treatment of each activity. The example does not classify the entire project from its final invoice title.']),
('Year End And Longer Payroll Preservation',[3],['The year end package should contain project revenue detail, sales reconciliations, contractor documents, inventory and asset schedules, debts, annual wage support and unresolved notices. Give the preparer the actual work descriptions behind ambiguous receipts and vendor charges.','The 2026 NC-30 instructions direct retention of withholding records for at least ten years after the last filing of all required reports for the calendar year or the last payment of an amount due for that year, whichever is later. Apply that specific employer instruction rather than a generic three year assumption. Sales, income, federal and property records require separate review, especially where returns or trust tax payments remain unresolved.'])],[('North Carolina GS 105-164.22','https://ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_105/GS_105-164.22.html',['Sales and use record scope for retailers, contractors and consumers, exemption and facilitator evidence.']),('North Carolina 2026 Sales And Use Bulletins','https://www.ncdor.gov/sutb-2026pdf/open',['Activity classification, purchase tax support and real property contract documentation.']),('North Carolina 2026 Employer Withholding Instructions NC-30','https://www.ncdor.gov/income-tax-withholding-tables-and-instructions-employers/open',['Employee certificates, annual reconciliation and section 26 ten years after final reports or payment, whichever later.'])],['Sales retention is not reduced to the ordinary assessment period. Contractor classification, local sourcing, nonresident compensation and workforce obligations require individualized review.'])
d['pilots'].sort(key=lambda x:x['state'])
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Saved',len(d['pilots']))
